import { type Control, Controller, type FieldValues, type Path } from 'react-hook-form';
import { View } from 'react-native';

import { Input, type InputProps } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Text } from '@/components/ui/text';
import { cn } from '@/lib/utils';

interface FormFieldProps<T extends FieldValues> extends Omit<
  InputProps,
  'value' | 'onChangeText' | 'onBlur'
> {
  control: Control<T>;
  name: Path<T>;
  label?: string;
}

/** Controlled text input wired to react-hook-form, with label + inline error. */
export function FormField<T extends FieldValues>({
  control,
  name,
  label,
  ...inputProps
}: FormFieldProps<T>) {
  return (
    <View className="gap-1.5">
      {label ? <Label>{label}</Label> : null}
      <Controller
        control={control}
        name={name}
        render={({ field: { onChange, onBlur, value }, fieldState: { error } }) => (
          <>
            <Input
              value={(value as string) ?? ''}
              onChangeText={onChange}
              onBlur={onBlur}
              accessibilityLabel={label}
              {...inputProps}
              // RNR's Input has no `error` prop: it marks invalid state with
              // `aria-invalid`, which only styles on web. On native the border has
              // to be a class, so the invalid look lives here rather than in the
              // component. Last in the merge so it wins over any caller className.
              className={cn(inputProps.className, error && 'border-destructive')}
            />
            {error?.message ? (
              <Text className="text-sm text-destructive">{error.message}</Text>
            ) : null}
          </>
        )}
      />
    </View>
  );
}
